def solve_grid(grid):
    """
    Transform grid based on 2-edge position.
    """
    rows = len(grid)
    cols = len(grid[0])

    # Find 2-edge
    complete_2_row = None
    for r in range(rows):
        if all(c == 2 for c in grid[r]):
            complete_2_row = r
            break

    complete_2_col = None
    for c in range(cols - 1, -1, -1):
        if all(grid[r][c] == 2 for r in range(rows)):
            complete_2_col = c
            break

    result = [row[:] for row in grid]

    if complete_2_row is not None:
        # Compress along columns toward the 2-edge row
        for c in range(cols):
            values = [grid[r][c] for r in range(rows) if r != complete_2_row and grid[r][c] not in [0, 2]]

            # Clear the column except for the 2-edge row
            for r in range(rows):
                if r != complete_2_row:
                    result[r][c] = 0

            # Place values ending at the 2-edge row
            end_pos = complete_2_row - 1
            for i, v in enumerate(values):
                result[end_pos - i][c] = v

    elif complete_2_col is not None:
        # Compress along rows toward the 2-edge col
        for r in range(rows):
            values = [grid[r][c] for c in range(cols) if c != complete_2_col and grid[r][c] not in [0, 2]]

            # Clear the row except for the 2-edge col
            for c in range(cols):
                if c != complete_2_col:
                    result[r][c] = 0

            # Place values ending at the 2-edge col
            end_pos = complete_2_col - 1
            for i, v in enumerate(values):
                result[r][end_pos - i] = v

    return result

